module adsr_division (
  clk,
  rstn,
  dividend,
  divisor,
  remainder,
  quotient
)
;
input clk;
input rstn;
input [3:0] dividend;
input [19:0] divisor;
output [31:0] remainder;
output [3:0] quotient;
wire VCC;
wire GND;
  \(integer_division)/(adsr_division)(N=4,M=20,Q=32,LATENCY=16)  integer_division_inst (
    .clk(clk),
    .rstn(rstn),
    .dividend(dividend[3:0]),
    .divisor(divisor[19:0]),
    .quotient(quotient[3:0]),
    .remainder(remainder[31:0])
);
  VCC VCC_cZ (
    .V(VCC)
);
  GND GND_cZ (
    .G(GND)
);
  GSR GSR (
    .GSRI(VCC) 
);
endmodule /* adsr_division */
